// of the deterministic scenes; commands retain Redis syntax.
const bi = (ru, en) => ({ ru, en });
// The main caption carries one idea; detail preserves its complete explanation.
// Both language versions share the same scene and command.
const step = (ruTitle, enTitle, ruBody, enBody, command, ruDetail, enDetail) => ({
  title: bi(ruTitle, enTitle), body: bi(ruBody, enBody), command,
  detail: bi(ruDetail ?? ruBody, enDetail ?? enBody),
});
const src = (label, url) => ({ label, url:url.replace('/redis/redis/blob/8.0/',`/redis/redis/blob/${REDIS_COMMIT}/`) });

